وَأَخْبَرَنَا /94 إِسْمَاعِيلُ بْنُ مُحَمَّدِ بْنِ إِسْمَاعِيلَ L35221 /94 ، /94 وَإِسْمَاعِيلُ بْنُ عَلِيٍّ الدَّلَالُ L66313 /94 ، /94 وَمُحَمَّدُ بْنُ الْحَسَنِ الرَّقَّامُ L66314 /94 ، /94 وَالْحَسَنُ بْنُ أَنَسٍ L66315 /94 ، قَالُوا : أَخْبَرَنَا /26 مُحَمَّدُ بْنُ مُحَمَّدِ بْنِ جَعْفَرِ بْنِ مَحْمُودِ بْنِ حَسَّانٍ L75507 /26 ، حَدَّثَنَا /26 أَحْمَدُ بْنُ مُحَمَّدِ بْنِ عَلِيِّ بْنِ    رَزِينٍ L10038 /26 ،   @ 2 : 100 @  حَدَّثَنَا /26 عَبْدُ الرَّحِيمِ بْنُ حَبِيبٍ L21046 /26 ، حَدَّثَنَا /26 إِسْحَاقُ بْنُ نَجِيحٍ L972 /26 ، عَنِ /26 الَأوزاعي L4457 /26 ، /26 وَابْنِ أَبِي رَوَّادٍ L4555 /26 . ح وَأَخْبَرَنِي /94 غَالِبُ بْنُ عَلِيٍّ L53964 /94 ، أَخْبَرَنَا /26 مُحَمَّدُ بْنُ الْحُسَيْنِ L46869 /26 ، حَدَّثَنَا /26 مُحَمَّدُ بْنُ الْحَسَنِ السَّرَّاجُ L27591 /26 ، حَدَّثَنَا /26 مُطَيَّنٌ L29740 /26 ، حَدَّثَنَا /26 سُوَيْدُ بْنُ سَعِيدٍ L3711 /26 ، حَدَّثَنَا /26 ابْنُ أَبِي الرِّجَالِ L4263 /26 ، حَدَّثَنَا /26 ابْنُ أَبِي رَوَّادٍ L4555 /26 ، عَنْ /26 نَافِعٍ L7863 /26 ، /27 عَنِ /93 ابْنِ عُمَرَ L4967 /93 رَضِيَ اللَّهُ عَنْهُمَا ، قَالَ : قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : /20 " مَنْ قَالَ فِي دِينِنَا بِرَأْيِهِ فَاقْتِلُوهُ " /27 ، لَفْظُهُمَا سَوَاءٌ * 
)E101 @ 2 : 101 @ 
